draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  // head
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  // body
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 20 + 15 * Math.sin(t), H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 20 + 15 * Math.sin(t), H/2 + 130);
  ctx.stroke();
  ctx.restore();
}
